create or replace function public.co_generar_alertas_servicios()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer := 0;
  v_row record;
begin
  for v_row in
    select s.*
    from public.co_servicios s
    where s.estado = 'activo'
      and s.proxima_fecha_pago <= current_date + s.anticipacion_dias
  loop
    if not exists (
      select 1
      from public.notificaciones_sistema n
      where n.tipo = 'servicio_proximo_pago'
        and n.entidad_id = v_row.id
        and n.created_at::date = current_date
    ) then
      insert into public.notificaciones_sistema(tipo,titulo,mensaje,entidad_id,leida)
      values(
        'servicio_proximo_pago',
        'Pago próximo · ' || v_row.nombre,
        coalesce(v_row.proveedor || ' · ', '') || 'Vence ' || to_char(v_row.proxima_fecha_pago,'DD/MM/YYYY') || ' · Aviso con ' || v_row.anticipacion_dias || ' días de anticipación.',
        v_row.id,
        false
      );
      v_count := v_count + 1;
    end if;
  end loop;
  return v_count;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'co_direcciones_entrega','co_solicitudes_proveedor','co_solicitud_proveedor_items',
    'co_tienda_solicitudes','co_servicios','co_servicio_pagos'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "Compras consulta %s" on public.%I', t, t);
    execute format('create policy "Compras consulta %s" on public.%I for select to authenticated using (exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in (''administrador'',''compras'',''jefe_almacen'')))', t, t);
    execute format('drop policy if exists "Compras administra %s" on public.%I', t, t);
    execute format('create policy "Compras administra %s" on public.%I for all to authenticated using (exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in (''administrador'',''compras''))) with check (exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in (''administrador'',''compras'')))', t, t);
  end loop;
end;
$$;

grant select,insert,update,delete on public.co_direcciones_entrega to authenticated;
