grant select,insert,update,delete on public.co_servicios to authenticated;
grant select,insert,update,delete on public.co_servicio_pagos to authenticated;
grant usage,select on all sequences in schema public to authenticated;
grant execute on function public.co_generar_alertas_servicios() to authenticated;

commit;

select
  case when to_regclass('public.co_direcciones_entrega') is not null then 'OK' else 'FALTA' end as entregas,
  case when to_regclass('public.co_solicitudes_proveedor') is not null then 'OK' else 'FALTA' end as solicitudes_proveedor,
  case when to_regclass('public.co_tienda_solicitudes') is not null then 'OK' else 'FALTA' end as tienda,
  case when to_regclass('public.co_servicios') is not null then 'OK' else 'FALTA' end as servicios,
  case when exists(select 1 from information_schema.columns where table_schema='public' and table_name='solicitudes_compra' and column_name='estado_compras') then 'OK' else 'FALTA' end as estado_compras;



begin;

alter table if exists public.existencias_almacen
    add column if not exists stock_medio numeric not null default 0,
    add column if not exists stock_maximo numeric not null default 0;

alter table if exists public.solicitudes_compra
    add column if not exists stock_medio numeric not null default 0,
    add column if not exists stock_maximo numeric not null default 0;

update public.existencias_almacen
set stock_maximo = case when coalesce(stock_minimo,0) > 0 then stock_minimo * 2 else 1 end
where coalesce(stock_maximo,0) <= 0;

update public.existencias_almacen
set stock_medio = (coalesce(stock_minimo,0) + coalesce(stock_maximo,0)) / 2
where coalesce(stock_medio,0) <= 0;

update public.existencias_almacen
set stock_maximo = greatest(coalesce(stock_maximo,0),coalesce(stock_minimo,0)),
    stock_medio = least(greatest(coalesce(stock_medio,0),coalesce(stock_minimo,0)),greatest(coalesce(stock_maximo,0),coalesce(stock_minimo,0)));

commit;

select 'OK' as estado, count(*) as existencias_con_niveles
from public.existencias_almacen
where stock_maximo >= stock_medio and stock_medio >= stock_minimo;


begin;

create table if not exists public.vehiculos(
    id bigint generated by default as identity primary key,
    numero_economico text not null unique,
    placas text,
    vin text,
    marca text not null,
