    anio integer,
    tipo text not null default 'pickup',
    color text,
    combustible text,
    transmision text,
    capacidad_carga numeric not null default 0,
    kilometraje numeric not null default 0,
    propiedad text not null default 'empresa',
    estado text not null default 'disponible',
    almacen_base_id bigint references public.almacenes(id) on update cascade on delete set null,
    proyecto text,
    asignado_a text,
    responsable text,
    aseguradora text,
    poliza_seguro text,
    vigencia_seguro date,
    tarjeta_circulacion text,
    vigencia_tarjeta date,
    proxima_verificacion date,
    fecha_adquisicion date,
    costo_adquisicion numeric not null default 0,
