do $$
begin
    if not exists(
        select 1 from public.ubicaciones_almacen
        where coalesce(btrim(codigo),'')<>''
          and upper(btrim(codigo)) !~ '^(0[1-9]|1[0-9]|20)-[1-9][0-9]*-[A-Z]$'
    ) and not exists(
        select 1 from public.existencias_almacen
        where coalesce(btrim(ubicacion),'')<>''
          and upper(btrim(ubicacion)) !~ '^(0[1-9]|1[0-9]|20)-[1-9][0-9]*-[A-Z][1-9][0-9]*$'
    ) then
        execute 'create unique index if not exists ubicaciones_almacen_estructura_v2_uq on public.ubicaciones_almacen(almacen_id,rack_numero,zona_numero,piso_letra) where rack_numero is not null and zona_numero is not null and piso_letra is not null';
    end if;
end;
$$;

drop index if exists public.existencias_almacen_ubicacion_v2_uq;
create index if not exists existencias_almacen_ubicacion_v34_idx
on public.existencias_almacen(almacen_id,(upper(btrim(ubicacion))))
where coalesce(btrim(ubicacion),'')<>'';

create or replace function public.crm_validar_existencia_ubicacion_v2()
returns trigger
language plpgsql
set search_path=public
as $$
declare
    v_partes text[];
    v_base text;
    v_consecutivo integer;
    v_capacidad integer;
    v_ocupados integer;
begin
    if coalesce(btrim(new.ubicacion),'')='' then
        new.ubicacion:=null;
        return new;
    end if;
    new.ubicacion:=upper(btrim(new.ubicacion));
    v_partes:=regexp_match(new.ubicacion,'^(0[1-9]|1[0-9]|20)-([1-9][0-9]*)-([A-Z])([1-9][0-9]*)$');
    if v_partes is null then
        raise exception 'Ubicación inválida: %. Usa RR-Z-PPOS, por ejemplo 01-1-A1.',new.ubicacion;
    end if;
    v_base:=v_partes[1]||'-'||v_partes[2]||'-'||v_partes[3];
    v_consecutivo:=v_partes[4]::integer;
    select greatest(1,coalesce(u.capacidad_consecutivos,u.columnas,20)) into v_capacidad
    from public.ubicaciones_almacen u
    where u.almacen_id=new.almacen_id and upper(btrim(u.codigo))=v_base and coalesce(u.estado,'Activo')='Activo'
    limit 1;
    if v_capacidad is null then raise exception 'No existe la estructura % en el almacén %.',v_base,new.almacen_id; end if;
    if v_consecutivo>v_capacidad then raise exception '% admite posiciones del 1 al %.',v_base,v_capacidad; end if;
    select count(*) into v_ocupados
    from public.existencias_almacen e
    where e.almacen_id=new.almacen_id
      and upper(btrim(coalesce(e.ubicacion,'')))=new.ubicacion
      and e.material_codigo<>new.material_codigo;
    if v_ocupados>=7 then raise exception 'La posición % ya contiene 7 tipos de material.',new.ubicacion; end if;
    return new;
end;
$$;

drop trigger if exists trg_existencias_almacen_ubicacion_v2 on public.existencias_almacen;
create trigger trg_existencias_almacen_ubicacion_v2
before insert or update of ubicacion,almacen_id on public.existencias_almacen
for each row execute function public.crm_validar_existencia_ubicacion_v2();

commit;


begin;

create or replace function public.crm_eliminar_movimiento_prueba(
    p_request_id text default null,
    p_movimiento_id bigint default null
) returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_request text:=btrim(coalesce(p_request_id,''));
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if v_request='' and coalesce(p_movimiento_id,0)<=0 then
        raise exception 'Falta identificar el movimiento.';
    end if;

    if to_regclass('public.ubicaciones_pendientes') is not null and v_request<>'' then
        execute 'delete from public.ubicaciones_pendientes where request_id=$1' using v_request;
    end if;

    if v_request<>'' then
        delete from public.movimientos where request_id=v_request;
    else
        delete from public.movimientos where id=p_movimiento_id;
    end if;
    get diagnostics v_count=row_count;

    if v_count=0 then
        raise exception 'No se encontró el movimiento solicitado.';
    end if;

    return jsonb_build_object(
        'ok',true,
        'eliminados',v_count,
        'requestId',nullif(v_request,''),
        'advertencia','Se eliminó el historial. Las existencias físicas no se recalculan automáticamente.'
    );
end;
$$;

revoke all on function public.crm_eliminar_movimiento_prueba(text,bigint) from public,anon;
grant execute on function public.crm_eliminar_movimiento_prueba(text,bigint) to authenticated;

create or replace function public.crm_eliminar_solicitud_material_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_project text;
    v_code text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    select proyecto_numero,material_codigo into v_project,v_code
    from public.proyecto_materiales where id=p_id;
    if not found then raise exception 'No se encontró la solicitud de material.'; end if;

    if to_regclass('public.reajustes_solicitud_material') is not null then
        execute 'delete from public.reajustes_solicitud_material where proyecto_numero=$1 and material_codigo=$2' using v_project,v_code;
    end if;
    if to_regclass('public.notificaciones_sistema') is not null then
        execute 'delete from public.notificaciones_sistema where proyecto_numero=$1 and material_codigo=$2' using v_project,v_code;
    end if;

    delete from public.proyecto_materiales where id=p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'proyecto',v_project,'codigo',v_code);
end;
$$;

revoke all on function public.crm_eliminar_solicitud_material_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_solicitud_material_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_reajuste_material_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_project text;
    v_code text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.reajustes_solicitud_material') is null then
        raise exception 'No existe el módulo de reajustes.';
    end if;
    execute 'select proyecto_numero,material_codigo from public.reajustes_solicitud_material where id=$1'
        into v_project,v_code using p_id;
    if v_project is null then raise exception 'No se encontró el reajuste.'; end if;
    if to_regclass('public.notificaciones_sistema') is not null then
        execute 'delete from public.notificaciones_sistema where entidad_id=$1 and tipo=''reajuste_solicitud_material''' using p_id;
    end if;
    execute 'delete from public.reajustes_solicitud_material where id=$1' using p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'proyecto',v_project,'codigo',v_code);
end;
$$;

