create or replace function public.crm_eliminar_vehiculo_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.vehiculos_gastos') is not null then execute 'delete from public.vehiculos_gastos where vehiculo_id=$1' using p_id; end if;
    if to_regclass('public.vehiculos_viajes') is not null then execute 'delete from public.vehiculos_viajes where vehiculo_id=$1' using p_id; end if;
    delete from public.vehiculos where id=p_id;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se encontró el vehículo.'; end if;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id);
end;
$$;

revoke all on function public.crm_eliminar_vehiculo_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_vehiculo_prueba(bigint) to authenticated;


create or replace function public.crm_eliminar_unidad_herramienta_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_tool bigint;
    v_code text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    select herramienta_id,codigo_interno into v_tool,v_code from public.herramientas_unidades where id=p_id;
    if not found then raise exception 'No se encontró la unidad de herramienta.'; end if;
    if to_regclass('public.herramientas_historial') is not null then
        execute 'delete from public.herramientas_historial where unidad_id=$1' using p_id;
    end if;
    if to_regclass('public.herramientas_asignaciones') is not null then
        execute 'delete from public.herramientas_asignaciones where unidad_id=$1' using p_id;
    end if;
    delete from public.herramientas_unidades where id=p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id,'codigo',v_code,'herramienta_id',v_tool);
end;
$$;

revoke all on function public.crm_eliminar_unidad_herramienta_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_unidad_herramienta_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_asignacion_herramienta_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_unit bigint;
    v_status text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.herramientas_asignaciones') is null then
        raise exception 'No existe el módulo de asignaciones de herramientas.';
    end if;
    execute 'select unidad_id,estado from public.herramientas_asignaciones where id=$1' into v_unit,v_status using p_id;
    if v_unit is null then raise exception 'No se encontró la asignación.'; end if;
    if to_regclass('public.herramientas_historial') is not null then
        execute 'delete from public.herramientas_historial where asignacion_id=$1' using p_id;
    end if;
    execute 'delete from public.herramientas_asignaciones where id=$1' using p_id;
    get diagnostics v_count=row_count;
    if lower(coalesce(v_status,''))='activa' then
        update public.herramientas_unidades
        set estado='disponible',asignado_a=null,proyecto=null,updated_at=now()
        where id=v_unit;
    end if;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id,'unidad_id',v_unit);
end;
$$;

revoke all on function public.crm_eliminar_asignacion_herramienta_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_asignacion_herramienta_prueba(bigint) to authenticated;

