begin;

create or replace function public.crm_chat_expira_hoy()
returns timestamptz
language sql
stable
set search_path=public
as $$
    select ((date_trunc('day', timezone('America/Mexico_City', now())) + interval '1 day' - interval '1 second') at time zone 'America/Mexico_City');
$$;

create table if not exists public.crm_chat_mensajes (
    id bigint generated by default as identity primary key,
    autor_id uuid not null references auth.users(id) on delete cascade,
    destinatario_id uuid references auth.users(id) on delete cascade,
    mensaje text not null,
    creado_at timestamptz not null default now(),
    expira_at timestamptz not null default public.crm_chat_expira_hoy(),
    constraint crm_chat_mensaje_longitud check (char_length(btrim(mensaje)) between 1 and 1500)
);

create index if not exists crm_chat_mensajes_creado_idx on public.crm_chat_mensajes(creado_at desc);
create index if not exists crm_chat_mensajes_destino_idx on public.crm_chat_mensajes(destinatario_id,creado_at desc);
create index if not exists crm_chat_mensajes_expira_idx on public.crm_chat_mensajes(expira_at);

alter table public.crm_chat_mensajes enable row level security;

drop policy if exists crm_chat_select on public.crm_chat_mensajes;
create policy crm_chat_select on public.crm_chat_mensajes
for select to authenticated
using (
    expira_at > now()
    and (
        destinatario_id is null
        or autor_id = auth.uid()
        or destinatario_id = auth.uid()
    )
);

drop policy if exists crm_chat_insert on public.crm_chat_mensajes;
create policy crm_chat_insert on public.crm_chat_mensajes
for insert to authenticated
with check (
    autor_id = auth.uid()
    and exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and coalesce(p.rol,'')<>'sky_demo')
);

drop policy if exists crm_chat_delete_own on public.crm_chat_mensajes;
create policy crm_chat_delete_own on public.crm_chat_mensajes
for delete to authenticated
using (
    autor_id=auth.uid()
    or exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol='administrador')
);

grant select,insert,delete on public.crm_chat_mensajes to authenticated;
grant usage,select on sequence public.crm_chat_mensajes_id_seq to authenticated;

create or replace function public.crm_chat_limpiar()
returns integer
language plpgsql
security definer
set search_path=public
as $$
declare v_count integer;
begin
    delete from public.crm_chat_mensajes where expira_at <= now();
    get diagnostics v_count = row_count;
    return v_count;
end;
$$;
revoke all on function public.crm_chat_limpiar() from public,anon;
grant execute on function public.crm_chat_limpiar() to authenticated;

create or replace function public.crm_chat_usuarios()
returns table(id uuid,nombre text,rol text,puesto text,departamento text)
language sql
security definer
set search_path=public
as $$
    select p.id,
           coalesce(nullif(btrim(p.nombre),''),'Usuario') as nombre,
           coalesce(nullif(btrim(p.rol),''),'consulta') as rol,
           coalesce(p.puesto,'') as puesto,
           coalesce(p.departamento,'') as departamento
    from public.perfiles_usuario p
    where p.activo=true and p.id<>auth.uid()
    order by p.nombre nulls last,p.rol;
$$;
revoke all on function public.crm_chat_usuarios() from public,anon;
grant execute on function public.crm_chat_usuarios() to authenticated;

create or replace function public.crm_chat_listar(p_destinatario uuid default null)
returns table(
    id bigint,
    autor_id uuid,
    autor_nombre text,
    destinatario_id uuid,
    destinatario_nombre text,
    mensaje text,
    creado_at timestamptz,
    expira_at timestamptz
)
language plpgsql
security definer
set search_path=public
as $$
declare
    v_inicio timestamptz;
begin
    if auth.uid() is null then
        raise exception using errcode='42501',message='La sesión no está activa.';
    end if;
    perform public.crm_chat_limpiar();
    v_inicio := ((date_trunc('day', timezone('America/Mexico_City', now())) + interval '1 hour') at time zone 'America/Mexico_City');
    return query
    select m.id,m.autor_id,
           coalesce(nullif(a.nombre,''),'Usuario') as autor_nombre,
           m.destinatario_id,
           coalesce(nullif(d.nombre,''),'') as destinatario_nombre,
           m.mensaje,m.creado_at,m.expira_at
    from public.crm_chat_mensajes m
    left join public.perfiles_usuario a on a.id=m.autor_id
    left join public.perfiles_usuario d on d.id=m.destinatario_id
    where m.expira_at>now()
      and m.creado_at>=v_inicio
      and (
        (p_destinatario is null and m.destinatario_id is null)
        or
        (p_destinatario is not null and m.destinatario_id is not null and
          ((m.autor_id=auth.uid() and m.destinatario_id=p_destinatario)
           or (m.autor_id=p_destinatario and m.destinatario_id=auth.uid())))
      )
    order by m.creado_at asc
    limit 300;
end;
$$;
revoke all on function public.crm_chat_listar(uuid) from public,anon;
grant execute on function public.crm_chat_listar(uuid) to authenticated;

create or replace function public.crm_chat_enviar(p_mensaje text,p_destinatario uuid default null)
returns bigint
language plpgsql
security definer
set search_path=public
as $$
declare
    v_id bigint;
    v_text text:=btrim(coalesce(p_mensaje,''));
begin
    if auth.uid() is null then
        raise exception using errcode='42501',message='La sesión no está activa.';
    end if;
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and coalesce(p.rol,'')<>'sky_demo') then
        raise exception using errcode='42501',message='Tu perfil no está autorizado para enviar mensajes por el chat.';
    end if;
    if char_length(v_text)=0 then raise exception 'Escribe un mensaje.'; end if;
    if char_length(v_text)>1500 then raise exception 'El mensaje puede contener hasta 1500 caracteres.'; end if;
    if p_destinatario is not null and not exists(select 1 from public.perfiles_usuario p where p.id=p_destinatario and p.activo=true) then
        raise exception 'El destinatario no está disponible.';
    end if;
    perform public.crm_chat_limpiar();
    insert into public.crm_chat_mensajes(autor_id,destinatario_id,mensaje,expira_at)
    values(auth.uid(),p_destinatario,v_text,public.crm_chat_expira_hoy())
    returning id into v_id;
    return v_id;
end;
$$;
revoke all on function public.crm_chat_enviar(text,uuid) from public,anon;
grant execute on function public.crm_chat_enviar(text,uuid) to authenticated;

insert into public.perfiles_usuario as p(id,nombre,rol,activo,puesto,departamento)
