alter table public.rh_personal add column if not exists telefono_whatsapp text;
alter table public.rh_personal add column if not exists whatsapp_nomina boolean not null default false;

create table if not exists public.rh_nomina_periodos(
    id bigint generated by default as identity primary key,
    nombre text not null,
    fecha_inicio date not null,
    fecha_fin date not null,
    estado text not null default 'borrador' check(estado in ('borrador','revisada','cerrada','cancelada')),
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint rh_nomina_periodo_fechas check(fecha_fin>=fecha_inicio)
);

create table if not exists public.rh_nomina_detalles(
    id bigint generated by default as identity primary key,
    periodo_id bigint not null references public.rh_nomina_periodos(id) on delete cascade,
    personal_id bigint not null references public.rh_personal(id) on delete restrict,
    salario_base numeric(14,2) not null default 0,
    bonos numeric(14,2) not null default 0,
    descuentos numeric(14,2) not null default 0,
    total_neto numeric(14,2) not null default 0,
    observaciones text,
    estado text not null default 'pendiente' check(estado in ('pendiente','revisado','pagado','cancelado')),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(periodo_id,personal_id)
);

create table if not exists public.rh_nomina_envios(
    id bigint generated by default as identity primary key,
    detalle_id bigint not null references public.rh_nomina_detalles(id) on delete cascade,
    telefono text not null,
    canal text not null default 'whatsapp',
    estado text not null default 'pendiente',
    proveedor_id text,
    error text,
    enviado_at timestamptz,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now()
);

alter table public.rh_nomina_periodos enable row level security;
alter table public.rh_nomina_detalles enable row level security;
alter table public.rh_nomina_envios enable row level security;

drop policy if exists rh_nomina_periodos_select on public.rh_nomina_periodos;
create policy rh_nomina_periodos_select on public.rh_nomina_periodos for select to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh','finanzas']));
drop policy if exists rh_nomina_periodos_write on public.rh_nomina_periodos;
create policy rh_nomina_periodos_write on public.rh_nomina_periodos for all to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh'])) with check(public.crm_usuario_tiene_rol(array['administrador','rh']));
drop policy if exists rh_nomina_detalles_select on public.rh_nomina_detalles;
create policy rh_nomina_detalles_select on public.rh_nomina_detalles for select to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh','finanzas']));
drop policy if exists rh_nomina_detalles_write on public.rh_nomina_detalles;
create policy rh_nomina_detalles_write on public.rh_nomina_detalles for all to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh'])) with check(public.crm_usuario_tiene_rol(array['administrador','rh']));
drop policy if exists rh_nomina_envios_select on public.rh_nomina_envios;
create policy rh_nomina_envios_select on public.rh_nomina_envios for select to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh']));
drop policy if exists rh_nomina_envios_write on public.rh_nomina_envios;
create policy rh_nomina_envios_write on public.rh_nomina_envios for all to authenticated using(public.crm_usuario_tiene_rol(array['administrador','rh'])) with check(public.crm_usuario_tiene_rol(array['administrador','rh']));

grant select,insert,update,delete on public.rh_nomina_periodos,public.rh_nomina_detalles,public.rh_nomina_envios to authenticated;
grant usage,select on sequence public.rh_nomina_periodos_id_seq,public.rh_nomina_detalles_id_seq,public.rh_nomina_envios_id_seq to authenticated;

create or replace function public.crm_generar_nomina(p_inicio date,p_fin date,p_nombre text default null)
returns bigint
language plpgsql
security definer
set search_path=public
as $$
declare
    v_periodo bigint;
    v_semanas numeric;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','rh']) then raise exception 'Tu perfil no puede generar nómina.'; end if;
    if p_inicio is null or p_fin is null or p_fin<p_inicio then raise exception 'El periodo de nómina no es válido.'; end if;
    v_semanas := greatest((p_fin-p_inicio+1)::numeric/7.0,1.0/7.0);
    insert into public.rh_nomina_periodos(nombre,fecha_inicio,fecha_fin)
    values(coalesce(nullif(btrim(p_nombre),''),'Nómina '||to_char(p_inicio,'DD/MM/YYYY')||' - '||to_char(p_fin,'DD/MM/YYYY')),p_inicio,p_fin)
    returning id into v_periodo;

    insert into public.rh_nomina_detalles(periodo_id,personal_id,salario_base,total_neto)
    select v_periodo,p.id,
           round(greatest(0,coalesce(p.salario_semanal_calculado,p.salario,
             case when p.esquema_pago in ('semana','confianza') then p.tarifa_pago else 0 end,0))*v_semanas,2),
           round(greatest(0,coalesce(p.salario_semanal_calculado,p.salario,
             case when p.esquema_pago in ('semana','confianza') then p.tarifa_pago else 0 end,0))*v_semanas,2)
    from public.rh_personal p where p.estado='activo';
    return v_periodo;
end;
$$;
revoke all on function public.crm_generar_nomina(date,date,text) from public,anon;
grant execute on function public.crm_generar_nomina(date,date,text) to authenticated;

create table if not exists public.crm_limpieza_auditoria(
    id bigint generated by default as identity primary key,
    ejecutado_por uuid references auth.users(id) on delete set null default auth.uid(),
    categorias text[] not null,
    resultado jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now()
);
alter table public.crm_limpieza_auditoria enable row level security;
drop policy if exists crm_limpieza_auditoria_admin on public.crm_limpieza_auditoria;
create policy crm_limpieza_auditoria_admin on public.crm_limpieza_auditoria for select to authenticated using(public.crm_usuario_tiene_rol(array['administrador']));
grant select on public.crm_limpieza_auditoria to authenticated;
grant usage,select on sequence public.crm_limpieza_auditoria_id_seq to authenticated;

create or replace function public.crm_limpieza_resumen()
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare r jsonb:='{}'::jsonb; n bigint:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador']) then raise exception 'Solo Administrador puede consultar el centro de limpieza.'; end if;
    select count(*) into n from public.movimientos; r:=r||jsonb_build_object('historial_movimientos',n);
    select count(*) into n from public.proyectos; r:=r||jsonb_build_object('proyectos',n);
    select count(*) into n from public.materiales; r:=r||jsonb_build_object('materiales',n);
    if to_regclass('public.existencias_almacen') is not null then execute 'select count(*) from public.existencias_almacen' into n; else n:=0; end if; r:=r||jsonb_build_object('existencias',n);
    if to_regclass('public.herramientas_catalogo') is not null then execute 'select count(*) from public.herramientas_catalogo' into n; else n:=0; end if; r:=r||jsonb_build_object('herramientas',n);
    if to_regclass('public.herramientas_unidades') is not null then execute 'select count(*) from public.herramientas_unidades' into n; else n:=0; end if; r:=r||jsonb_build_object('unidades_herramientas',n);
    if to_regclass('public.solicitudes_compra') is not null then execute 'select count(*) from public.solicitudes_compra' into n; else n:=0; end if; r:=r||jsonb_build_object('compras',n);
    if to_regclass('public.vehiculos') is not null then execute 'select count(*) from public.vehiculos' into n; else n:=0; end if; r:=r||jsonb_build_object('vehiculos',n);
    if to_regclass('public.rh_incidencias') is not null then execute 'select count(*) from public.rh_incidencias' into n; else n:=0; end if; r:=r||jsonb_build_object('rh_operacion',n);
    if to_regclass('public.rh_personal') is not null then execute 'select count(*) from public.rh_personal' into n; else n:=0; end if; r:=r||jsonb_build_object('personal_rh',n);
    if to_regclass('public.crm_chat_mensajes') is not null then execute 'select count(*) from public.crm_chat_mensajes' into n; else n:=0; end if; r:=r||jsonb_build_object('chat',n);
    return r;
end;
$$;
revoke all on function public.crm_limpieza_resumen() from public,anon;
grant execute on function public.crm_limpieza_resumen() to authenticated;

create or replace function public.crm_limpiar_datos_prueba(p_categorias text[],p_clave text)
returns jsonb
language plpgsql
security definer
set search_path=public,storage
as $$
declare
    c text[]:=array(select lower(btrim(x)) from unnest(coalesce(p_categorias,array[]::text[])) x where btrim(x)<>'');
    result jsonb:='{}'::jsonb;
    n integer:=0;
    has_moves boolean:=false;
begin
    if not public.crm_usuario_tiene_rol(array['administrador']) then raise exception using errcode='42501',message='Solo Administrador puede borrar datos de prueba.'; end if;
    if md5(coalesce(p_clave,''))<>'81dc9bdb52d04dc20036dbd8313ed055' then raise exception using errcode='42501',message='La contraseña de limpieza es incorrecta.'; end if;
    if cardinality(c)=0 then raise exception 'Selecciona por lo menos un apartado.'; end if;
    has_moves := 'historial_movimientos'=any(c);

    if 'materiales'=any(c) and not has_moves and exists(select 1 from public.movimientos limit 1) then
        raise exception 'Para borrar Materiales también selecciona Historial de movimientos, porque existen movimientos que conservan referencias al catálogo.';
    end if;
    if 'proyectos'=any(c) and not has_moves and exists(select 1 from public.movimientos where coalesce(proyecto,'')<>'' limit 1) then
        raise exception 'Para borrar Proyectos también selecciona Historial de movimientos, porque existen movimientos relacionados.';
    end if;

    if 'chat'=any(c) and to_regclass('public.crm_chat_mensajes') is not null then execute 'delete from public.crm_chat_mensajes where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('chat',n); end if;

    if 'vehiculos'=any(c) then
        if to_regclass('public.vehiculos_viaje_pasajeros') is not null then execute 'delete from public.vehiculos_viaje_pasajeros where true'; end if;
        if to_regclass('public.vehiculos_gastos') is not null then execute 'delete from public.vehiculos_gastos where true'; end if;
        if to_regclass('public.vehiculos_viajes') is not null then execute 'delete from public.vehiculos_viajes where true'; end if;
        if to_regclass('public.vehiculos') is not null then execute 'delete from public.vehiculos where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('vehiculos',n); end if;
    end if;

    if 'personal_rh'=any(c) then
        if to_regclass('public.rh_nomina_envios') is not null then execute 'delete from public.rh_nomina_envios where true'; end if;
        if to_regclass('public.rh_nomina_detalles') is not null then execute 'delete from public.rh_nomina_detalles where true'; end if;
        if to_regclass('public.rh_nomina_periodos') is not null then execute 'delete from public.rh_nomina_periodos where true'; end if;
        if to_regclass('public.rh_proyecto_asignaciones') is not null then execute 'delete from public.rh_proyecto_asignaciones where true'; end if;
        if to_regclass('public.rh_capacitacion_participantes') is not null then execute 'delete from public.rh_capacitacion_participantes where true'; end if;
        if to_regclass('public.rh_documentos') is not null then execute 'delete from public.rh_documentos where true'; end if;
        if to_regclass('public.rh_incidencias') is not null then execute 'delete from public.rh_incidencias where true'; end if;
        delete from public.rh_personal where true; get diagnostics n=row_count; result:=result||jsonb_build_object('personal_rh',n);
    end if;

    if 'rh_operacion'=any(c) then
        if to_regclass('public.rh_nomina_envios') is not null then execute 'delete from public.rh_nomina_envios where true'; end if;
        if to_regclass('public.rh_nomina_detalles') is not null then execute 'delete from public.rh_nomina_detalles where true'; end if;
        if to_regclass('public.rh_nomina_periodos') is not null then execute 'delete from public.rh_nomina_periodos where true'; end if;
        if to_regclass('public.rh_capacitacion_participantes') is not null then execute 'delete from public.rh_capacitacion_participantes where true'; end if;
        if to_regclass('public.rh_capacitaciones') is not null then execute 'delete from public.rh_capacitaciones where true'; end if;
        if to_regclass('public.rh_documentos') is not null then execute 'delete from public.rh_documentos where true'; end if;
        if to_regclass('public.rh_incidencias') is not null then execute 'delete from public.rh_incidencias where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('rh_operacion',n); end if;
    end if;

    if 'compras'=any(c) then
        if to_regclass('public.co_solicitud_proveedor_items') is not null then execute 'delete from public.co_solicitud_proveedor_items where true'; end if;
        if to_regclass('public.co_solicitudes_proveedor') is not null then execute 'delete from public.co_solicitudes_proveedor where true'; end if;
        if to_regclass('public.co_cotizacion_ofertas') is not null then execute 'delete from public.co_cotizacion_ofertas where true'; end if;
        if to_regclass('public.co_cotizacion_items') is not null then execute 'delete from public.co_cotizacion_items where true'; end if;
        if to_regclass('public.co_cotizaciones') is not null then execute 'delete from public.co_cotizaciones where true'; end if;
        if to_regclass('public.co_tienda_solicitudes') is not null then execute 'delete from public.co_tienda_solicitudes where true'; end if;
        if to_regclass('public.co_servicio_pagos') is not null then execute 'delete from public.co_servicio_pagos where true'; end if;
        if to_regclass('public.reajustes_solicitud_material') is not null then execute 'delete from public.reajustes_solicitud_material where true'; end if;
        if to_regclass('public.solicitudes_compra') is not null then execute 'delete from public.solicitudes_compra where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('compras',n); end if;
        if to_regclass('public.notificaciones_sistema') is not null then execute 'delete from public.notificaciones_sistema where true'; end if;
    end if;

    if 'existencias'=any(c) then
        if to_regclass('public.existencias_proyecto_almacen') is not null then execute 'delete from public.existencias_proyecto_almacen where true'; end if;
        if to_regclass('public.ubicaciones_pendientes') is not null then execute 'delete from public.ubicaciones_pendientes where true'; end if;
        if to_regclass('public.existencias_almacen') is not null then execute 'delete from public.existencias_almacen where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('existencias',n); end if;
    end if;

    if has_moves then
        delete from public.movimientos where true; get diagnostics n=row_count; result:=result||jsonb_build_object('historial_movimientos',n);
        if to_regclass('public.prestamos_material_proyecto') is not null then execute 'delete from public.prestamos_material_proyecto where true'; end if;
        if to_regclass('public.ubicaciones_pendientes') is not null then execute 'delete from public.ubicaciones_pendientes where true'; end if;
    end if;

    if 'proyectos'=any(c) then
        if to_regclass('public.rh_proyecto_asignaciones') is not null then execute 'delete from public.rh_proyecto_asignaciones where true'; end if;
        if to_regclass('public.proyecto_herramientas') is not null then execute 'delete from public.proyecto_herramientas where true'; end if;
        if to_regclass('public.existencias_proyecto_almacen') is not null then execute 'delete from public.existencias_proyecto_almacen where true'; end if;
        if to_regclass('public.proyecto_materiales_no_listados') is not null then execute 'delete from public.proyecto_materiales_no_listados where true'; end if;
        if to_regclass('public.proyecto_materiales') is not null then execute 'delete from public.proyecto_materiales where true'; end if;
        delete from public.proyectos where true; get diagnostics n=row_count; result:=result||jsonb_build_object('proyectos',n);
    end if;

    if 'unidades_herramientas'=any(c) and not ('herramientas'=any(c)) then
        if to_regclass('public.herramientas_historial') is not null then execute 'delete from public.herramientas_historial where unidad_id is not null'; end if;
        if to_regclass('public.herramientas_asignaciones') is not null then execute 'delete from public.herramientas_asignaciones where true'; end if;
        if to_regclass('public.herramientas_unidades') is not null then execute 'delete from public.herramientas_unidades where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('unidades_herramientas',n); end if;
    end if;

    if 'herramientas'=any(c) then
        if to_regclass('public.herramientas_historial') is not null then execute 'delete from public.herramientas_historial where true'; end if;
        if to_regclass('public.herramientas_asignaciones') is not null then execute 'delete from public.herramientas_asignaciones where true'; end if;
        if to_regclass('public.proyecto_herramientas') is not null then execute 'delete from public.proyecto_herramientas where true'; end if;
        if to_regclass('public.herramientas_unidades') is not null then execute 'delete from public.herramientas_unidades where true'; end if;
        if to_regclass('public.herramientas_catalogo') is not null then execute 'delete from public.herramientas_catalogo where true'; get diagnostics n=row_count; result:=result||jsonb_build_object('herramientas',n); end if;
    end if;

    if 'materiales'=any(c) then
        if to_regclass('public.co_proveedor_materiales') is not null then execute 'delete from public.co_proveedor_materiales where true'; end if;
        if to_regclass('public.existencias_proyecto_almacen') is not null then execute 'delete from public.existencias_proyecto_almacen where true'; end if;
        if to_regclass('public.proyecto_materiales') is not null then execute 'delete from public.proyecto_materiales where true'; end if;
        if to_regclass('public.existencias_almacen') is not null then execute 'delete from public.existencias_almacen where true'; end if;
        if to_regclass('public.ubicaciones_pendientes') is not null then execute 'delete from public.ubicaciones_pendientes where true'; end if;
        delete from public.materiales where true; get diagnostics n=row_count; result:=result||jsonb_build_object('materiales',n);
    end if;

    insert into public.crm_limpieza_auditoria(categorias,resultado) values(c,result);
    return jsonb_build_object('ok',true,'categorias',c,'eliminados',result,'fecha',now());
end;
$$;
revoke all on function public.crm_limpiar_datos_prueba(text[],text) from public,anon;
grant execute on function public.crm_limpiar_datos_prueba(text[],text) to authenticated;

