create table if not exists public.crm_migraciones(version text primary key,aplicada_at timestamptz not null default now());

create table if not exists public.rh_activos_oficina(
    id bigint generated by default as identity primary key,
    codigo text not null,
    nombre text not null,
    categoria text not null default 'Otro',
    tipo_control text not null default 'individual',
    marca text,
    modelo text,
    numero_serie text,
    unidad text not null default 'PIEZA',
    cantidad_total numeric(14,2) not null default 1,
    ubicacion text,
    estado text not null default 'activo',
    observaciones text,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.rh_activos_oficina drop constraint if exists rh_activos_oficina_tipo_control_check;
alter table public.rh_activos_oficina add constraint rh_activos_oficina_tipo_control_check check(tipo_control in ('individual','cantidad'));
alter table public.rh_activos_oficina drop constraint if exists rh_activos_oficina_estado_check;
alter table public.rh_activos_oficina add constraint rh_activos_oficina_estado_check check(estado in ('activo','mantenimiento','baja'));
alter table public.rh_activos_oficina drop constraint if exists rh_activos_oficina_cantidad_check;
alter table public.rh_activos_oficina add constraint rh_activos_oficina_cantidad_check check(cantidad_total>0);
create unique index if not exists rh_activos_oficina_codigo_uq on public.rh_activos_oficina(lower(codigo));
create unique index if not exists rh_activos_oficina_serie_uq on public.rh_activos_oficina(lower(numero_serie)) where nullif(btrim(numero_serie),'') is not null;
create index if not exists rh_activos_oficina_categoria_idx on public.rh_activos_oficina(categoria,estado);

create table if not exists public.rh_activos_asignaciones(
    id bigint generated by default as identity primary key,
    activo_id bigint not null references public.rh_activos_oficina(id) on update cascade on delete restrict,
    personal_id bigint not null references public.rh_personal(id) on update cascade on delete restrict,
    cantidad numeric(14,2) not null default 1,
    fecha_asignacion date not null default current_date,
    fecha_devolucion date,
    estado text not null default 'asignado',
    condicion_entrega text,
    condicion_devolucion text,
    responsable_entrega text,
    responsable_recepcion text,
    notas text,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    cerrado_por uuid references auth.users(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.rh_activos_asignaciones drop constraint if exists rh_activos_asignaciones_estado_check;
alter table public.rh_activos_asignaciones add constraint rh_activos_asignaciones_estado_check check(estado in ('asignado','devuelto','danado','perdido'));
alter table public.rh_activos_asignaciones drop constraint if exists rh_activos_asignaciones_cantidad_check;
alter table public.rh_activos_asignaciones add constraint rh_activos_asignaciones_cantidad_check check(cantidad>0);
create index if not exists rh_activos_asignaciones_personal_idx on public.rh_activos_asignaciones(personal_id,estado);
create index if not exists rh_activos_asignaciones_activo_idx on public.rh_activos_asignaciones(activo_id,estado);
create index if not exists rh_activos_asignaciones_fecha_idx on public.rh_activos_asignaciones(fecha_asignacion desc);

create or replace function public.rh_activo_oficina_actualizar_trg()
returns trigger
language plpgsql
set search_path=public
as $$
declare v_ocupado numeric(14,2):=0;
begin
    new.codigo=upper(btrim(coalesce(new.codigo,'')));
    new.nombre=btrim(coalesce(new.nombre,''));
    new.categoria=coalesce(nullif(btrim(coalesce(new.categoria,'')),''),'Otro');
    new.unidad=upper(coalesce(nullif(btrim(coalesce(new.unidad,'')),''),'PIEZA'));
    if new.codigo='' or new.nombre='' then raise exception using errcode='22023',message='Código y nombre son obligatorios.'; end if;
    if new.tipo_control='individual' then new.cantidad_total=1;new.unidad='PIEZA';end if;
    if tg_op='UPDATE' then
        select coalesce(sum(a.cantidad),0) into v_ocupado from public.rh_activos_asignaciones a where a.activo_id=old.id and a.estado in ('asignado','danado','perdido');
        if new.cantidad_total<v_ocupado then raise exception using errcode='22023',message=format('La cantidad total no puede ser menor a %s, porque esa cantidad sigue asignada, dañada o perdida.',v_ocupado);end if;
    end if;
    new.updated_at=now();
    return new;
end;
$$;

drop trigger if exists trg_rh_activo_oficina_actualizar on public.rh_activos_oficina;
create trigger trg_rh_activo_oficina_actualizar before insert or update on public.rh_activos_oficina for each row execute function public.rh_activo_oficina_actualizar_trg();

drop trigger if exists trg_rh_activos_asignaciones_fecha on public.rh_activos_asignaciones;
create trigger trg_rh_activos_asignaciones_fecha before update on public.rh_activos_asignaciones for each row execute function public.rh_actualizar_fecha();

alter table public.rh_activos_oficina enable row level security;
alter table public.rh_activos_asignaciones enable row level security;

drop policy if exists "RH consulta activos oficina" on public.rh_activos_oficina;
create policy "RH consulta activos oficina" on public.rh_activos_oficina for select to authenticated using(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')));
drop policy if exists "RH administra activos oficina" on public.rh_activos_oficina;
create policy "RH administra activos oficina" on public.rh_activos_oficina for all to authenticated using(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))) with check(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')));

drop policy if exists "RH consulta resguardos" on public.rh_activos_asignaciones;
create policy "RH consulta resguardos" on public.rh_activos_asignaciones for select to authenticated using(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')) or exists(select 1 from public.rh_personal rp where rp.id=personal_id and rp.usuario_id=auth.uid()));
drop policy if exists "RH administra resguardos" on public.rh_activos_asignaciones;
create policy "RH administra resguardos" on public.rh_activos_asignaciones for all to authenticated using(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))) with check(exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')));

grant select,insert,update,delete on public.rh_activos_oficina to authenticated;
grant select,insert,update,delete on public.rh_activos_asignaciones to authenticated;
grant usage,select on sequence public.rh_activos_oficina_id_seq to authenticated;
grant usage,select on sequence public.rh_activos_asignaciones_id_seq to authenticated;

create or replace function public.rh_asignar_activo_oficina(p_activo_id bigint,p_personal_id bigint,p_cantidad numeric default 1,p_fecha_asignacion date default current_date,p_condicion_entrega text default null,p_responsable_entrega text default null,p_notas text default null)
returns bigint
language plpgsql
security definer
set search_path=public,auth
as $$
declare v_activo public.rh_activos_oficina%rowtype;v_ocupado numeric(14,2):=0;v_cantidad numeric(14,2);v_id bigint;
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')) then raise exception using errcode='42501',message='Solo RH puede registrar resguardos de equipo.';end if;
    select * into v_activo from public.rh_activos_oficina where id=p_activo_id for update;
    if not found then raise exception using errcode='P0002',message='El activo no existe.';end if;
    if v_activo.estado<>'activo' then raise exception using errcode='22023',message='El activo no está disponible para asignación.';end if;
    if not exists(select 1 from public.rh_personal rp where rp.id=p_personal_id and rp.estado<>'baja') then raise exception using errcode='22023',message='El colaborador no existe o está dado de baja.';end if;
    select coalesce(sum(a.cantidad),0) into v_ocupado from public.rh_activos_asignaciones a where a.activo_id=p_activo_id and a.estado in ('asignado','danado','perdido');
    v_cantidad=case when v_activo.tipo_control='individual' then 1 else greatest(coalesce(p_cantidad,1),0) end;
    if v_cantidad<=0 then raise exception using errcode='22023',message='La cantidad debe ser mayor a cero.';end if;
    if v_ocupado+v_cantidad>v_activo.cantidad_total then raise exception using errcode='22023',message=format('Solo hay %s %s disponibles.',greatest(v_activo.cantidad_total-v_ocupado,0),v_activo.unidad);end if;
    insert into public.rh_activos_asignaciones(activo_id,personal_id,cantidad,fecha_asignacion,estado,condicion_entrega,responsable_entrega,notas,creado_por) values(p_activo_id,p_personal_id,v_cantidad,coalesce(p_fecha_asignacion,current_date),'asignado',nullif(btrim(coalesce(p_condicion_entrega,'')),''),nullif(btrim(coalesce(p_responsable_entrega,'')),''),nullif(btrim(coalesce(p_notas,'')),''),auth.uid()) returning id into v_id;
    return v_id;
end;
$$;
revoke all on function public.rh_asignar_activo_oficina(bigint,bigint,numeric,date,text,text,text) from public,anon;
grant execute on function public.rh_asignar_activo_oficina(bigint,bigint,numeric,date,text,text,text) to authenticated;

create or replace function public.rh_cerrar_asignacion_activo_oficina(p_asignacion_id bigint,p_resultado text default 'devuelto',p_fecha_devolucion date default current_date,p_condicion_devolucion text default null,p_responsable_recepcion text default null,p_notas text default null)
returns bigint
language plpgsql
security definer
set search_path=public,auth
as $$
declare v_estado text:=lower(btrim(coalesce(p_resultado,'devuelto')));v_id bigint;
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')) then raise exception using errcode='42501',message='Solo RH puede cerrar resguardos de equipo.';end if;
    if v_estado not in ('devuelto','danado','perdido') then raise exception using errcode='22023',message='Resultado de devolución no válido.';end if;
    update public.rh_activos_asignaciones set estado=v_estado,fecha_devolucion=coalesce(p_fecha_devolucion,current_date),condicion_devolucion=nullif(btrim(coalesce(p_condicion_devolucion,'')),''),responsable_recepcion=nullif(btrim(coalesce(p_responsable_recepcion,'')),''),notas=case when nullif(btrim(coalesce(p_notas,'')),'') is null then notas when nullif(btrim(coalesce(notas,'')),'') is null then btrim(p_notas) else notas||E'\n'||btrim(p_notas) end,cerrado_por=auth.uid(),updated_at=now() where id=p_asignacion_id and estado='asignado' returning id into v_id;
    if v_id is null then raise exception using errcode='P0002',message='El resguardo no existe o ya fue cerrado.';end if;
    return v_id;
end;
$$;
revoke all on function public.rh_cerrar_asignacion_activo_oficina(bigint,text,date,text,text,text) from public,anon;
grant execute on function public.rh_cerrar_asignacion_activo_oficina(bigint,text,date,text,text,text) to authenticated;

create or replace function public.rh_eliminar_activo_oficina(p_activo_id bigint)
returns boolean
language plpgsql
security definer
set search_path=public,auth
as $$
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh')) then raise exception using errcode='42501',message='Solo RH puede eliminar activos.';end if;
    if exists(select 1 from public.rh_activos_asignaciones where activo_id=p_activo_id) then raise exception using errcode='23503',message='El activo tiene historial de resguardos. Cámbialo a Baja para conservar la trazabilidad.';end if;
    delete from public.rh_activos_oficina where id=p_activo_id;
    return found;
end;
$$;
revoke all on function public.rh_eliminar_activo_oficina(bigint) from public,anon;
grant execute on function public.rh_eliminar_activo_oficina(bigint) to authenticated;

create or replace function public.crm_sky_direccion_activos_oficina()
returns jsonb
language plpgsql
stable
security definer
set search_path=public,auth
as $$
declare v_activos jsonb;v_asignaciones jsonb;
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','gerente_general','subgerente')) then raise exception using errcode='42501',message='Esta consulta de Sky está disponible solo para Dirección.';end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'codigo',x.codigo,'nombre',x.nombre,'categoria',x.categoria,'marca',x.marca,'modelo',x.modelo,'numeroSerie',x.numero_serie,'unidad',x.unidad,'cantidadTotal',x.cantidad_total,'asignado',x.asignado,'noDisponible',x.no_disponible,'disponible',greatest(x.cantidad_total-x.no_disponible,0),'ubicacion',x.ubicacion,'estado',x.estado) order by x.nombre),'[]'::jsonb) into v_activos from (select a.*,coalesce(sum(r.cantidad) filter(where r.estado='asignado'),0) asignado,coalesce(sum(r.cantidad) filter(where r.estado in ('asignado','danado','perdido')),0) no_disponible from public.rh_activos_oficina a left join public.rh_activos_asignaciones r on r.activo_id=a.id group by a.id)x;
    select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'activoId',a.id,'activoCodigo',a.codigo,'activoNombre',a.nombre,'categoria',a.categoria,'marca',a.marca,'modelo',a.modelo,'numeroSerie',a.numero_serie,'unidad',a.unidad,'personalId',p.id,'personalNumero',p.numero_empleado,'personalNombre',btrim(coalesce(p.nombre,'')||' '||coalesce(p.apellidos,'')),'puesto',p.puesto,'departamento',p.departamento,'cantidad',r.cantidad,'fechaAsignacion',r.fecha_asignacion,'fechaDevolucion',r.fecha_devolucion,'estado',r.estado,'condicionEntrega',r.condicion_entrega,'condicionDevolucion',r.condicion_devolucion,'responsableEntrega',r.responsable_entrega,'responsableRecepcion',r.responsable_recepcion) order by r.fecha_asignacion desc,r.id desc),'[]'::jsonb) into v_asignaciones from public.rh_activos_asignaciones r join public.rh_activos_oficina a on a.id=r.activo_id join public.rh_personal p on p.id=r.personal_id;
    return jsonb_build_object('activos',v_activos,'asignaciones',v_asignaciones);
end;
$$;
revoke all on function public.crm_sky_direccion_activos_oficina() from public,anon;
grant execute on function public.crm_sky_direccion_activos_oficina() to authenticated;

insert into public.crm_migraciones(version) values('V46_RH_EQUIPOS_RESguardos_SKY') on conflict(version) do nothing;
notify pgrst,'reload schema';
commit;

select 'OK' estado,(select count(*) from public.rh_activos_oficina) activos_oficina,(select count(*) from public.rh_activos_asignaciones where estado='asignado') resguardos_activos;

begin;

alter table public.perfiles_usuario drop constraint if exists perfiles_usuario_rol_check;
alter table public.perfiles_usuario add constraint perfiles_usuario_rol_check
check (lower(btrim(rol)) in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','gerente_general','subgerente','tsi','sky_demo','consulta'));

create or replace function public.crm_asignar_rol_por_correo(
    p_correo text,
    p_rol text,
    p_activo boolean default true
)
returns public.perfiles_usuario
language plpgsql
security definer
set search_path=public,auth
as $$
declare
    v_usuario_id uuid;
    v_perfil public.perfiles_usuario%rowtype;
    v_jwt_role text:=coalesce(current_setting('request.jwt.claim.role',true),'');
begin
    p_rol:=lower(btrim(p_rol));
    if p_rol not in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','gerente_general','subgerente','tsi','sky_demo','consulta') then raise exception 'Rol no válido: %',p_rol; end if;
    if auth.uid() is not null then
        if not public.crm_usuario_tiene_rol(array['administrador']) then raise exception using errcode='42501',message='Solo un administrador activo puede asignar roles.'; end if;
    elsif session_user not in ('postgres','supabase_admin') and v_jwt_role<>'service_role' then
        raise exception using errcode='42501',message='La asignación de roles requiere administrador o service_role.';
    end if;
    select id into v_usuario_id from auth.users where lower(email)=lower(btrim(p_correo)) limit 1;
    if v_usuario_id is null then raise exception 'No existe un usuario con el correo %',p_correo; end if;
    insert into public.perfiles_usuario(id,nombre,rol,activo)
    select u.id,coalesce(nullif(u.raw_user_meta_data->>'nombre',''),split_part(u.email,'@',1)),p_rol,p_activo from auth.users u where u.id=v_usuario_id
    on conflict(id) do update set rol=excluded.rol,activo=excluded.activo,updated_at=now()
    returning * into v_perfil;
    return v_perfil;
end;
$$;

revoke all on function public.crm_asignar_rol_por_correo(text,text,boolean) from public,anon;
grant execute on function public.crm_asignar_rol_por_correo(text,text,boolean) to authenticated,service_role;

create or replace function public.crm_es_direccion()
returns boolean
language sql
stable
security definer
set search_path=public,auth
as $$
    select auth.uid() is not null and exists(
        select 1
        from public.perfiles_usuario p
        where p.id=auth.uid()
          and p.activo=true
          and p.rol in ('administrador','gerente_general','subgerente','sky_demo')
    );
$$;
revoke all on function public.crm_es_direccion() from public,anon;
grant execute on function public.crm_es_direccion() to authenticated;

create or replace function public.crm_resumen_ejecutivo_proyectos()
returns table(
    proyecto text,nombre text,cliente text,responsable text,estado text,fecha_inicio date,fecha_entrega date,
    material_planeado numeric,material_real numeric,nomina_planeada numeric,nomina_real numeric,total_planeado numeric,total_real numeric,desviacion_total numeric
)
language plpgsql
security definer
set search_path=public
as $$
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','gerente_general','subgerente','sky_demo')) then
        raise exception using errcode='42501',message='Este resumen está disponible solo para Dirección.';
    end if;
    return query
    with plan_lines as (
        select pm.proyecto_numero,pm.material_codigo codigo,coalesce(pm.cantidad_planeada,0)::numeric cantidad,
               coalesce(nullif(pm.precio_unitario,0),m.precio,0)::numeric precio
        from public.proyecto_materiales pm left join public.materiales m on m.codigo=pm.material_codigo
        union all
        select pn.proyecto_numero,pn.codigo_manual,coalesce(pn.cantidad_planeada,0)::numeric,
               coalesce(pn.precio_unitario,0)::numeric
        from public.proyecto_materiales_no_listados pn
    ), material_plan as (
        select proyecto_numero,sum(cantidad*precio)::numeric material_planeado from plan_lines group by proyecto_numero
    ), move_code as (
        select mv.proyecto proyecto_numero,coalesce(nullif(mv.material_codigo,''),nullif(mv.codigo_manual,'')) codigo,
               sum(case when lower(coalesce(mv.tipo,''))='entrada' then coalesce(mv.cantidad,0) else 0 end)::numeric entrada,
               sum(case when lower(coalesce(mv.tipo,''))='salida' then coalesce(mv.cantidad,0)
                        when lower(coalesce(mv.tipo,''))='reingreso' then -coalesce(mv.cantidad,0)
                        when lower(coalesce(mv.tipo,''))='ajuste' and lower(coalesce(mv.ajuste_accion,''))='disminuir' then coalesce(mv.cantidad,0)
                        else 0 end)::numeric entregado,
               max(coalesce(nullif(mv.precio_unitario,0),m.precio,0))::numeric precio
        from public.movimientos mv left join public.materiales m on m.codigo=mv.material_codigo
        where nullif(btrim(coalesce(mv.proyecto,'')),'') is not null
        group by mv.proyecto,coalesce(nullif(mv.material_codigo,''),nullif(mv.codigo_manual,''))
    ), material_real as (
        select proyecto_numero,sum(greatest(coalesce(entrada,0),greatest(coalesce(entregado,0),0))*coalesce(precio,0))::numeric material_real
        from move_code group by proyecto_numero
    ), payroll as (
        select a.proyecto_numero,
          sum((case when rp.esquema_pago='hora' then coalesce(rp.tarifa_pago,0)*greatest(coalesce(rp.horas_jornada_diaria,8)-coalesce(rp.horas_comida_diaria,1),0)
                    else coalesce(nullif(rp.salario_semanal_calculado,0),rp.tarifa_pago,rp.salario,0)/greatest(coalesce(rp.dias_laborales_semana,6),1) end)
              * greatest(0,(coalesce(a.fecha_fin,p.fecha_entrega,current_date)-a.fecha_inicio+1)) * greatest(coalesce(rp.dias_laborales_semana,6),1)/7.0
              * coalesce(a.porcentaje_dedicacion,100)/100.0)::numeric nomina_planeada,
          sum((case when rp.esquema_pago='hora' then coalesce(rp.tarifa_pago,0)*greatest(coalesce(rp.horas_jornada_diaria,8)-coalesce(rp.horas_comida_diaria,1),0)
                    else coalesce(nullif(rp.salario_semanal_calculado,0),rp.tarifa_pago,rp.salario,0)/greatest(coalesce(rp.dias_laborales_semana,6),1) end)
              * greatest(0,(least(current_date,coalesce(a.fecha_fin,p.fecha_entrega,current_date))-a.fecha_inicio+1)) * greatest(coalesce(rp.dias_laborales_semana,6),1)/7.0
              * coalesce(a.porcentaje_dedicacion,100)/100.0)::numeric nomina_real
        from public.rh_proyecto_asignaciones a join public.rh_personal rp on rp.id=a.personal_id join public.proyectos p on p.numero_proyecto=a.proyecto_numero
        where a.estado<>'cancelado'
        group by a.proyecto_numero
    )
    select p.numero_proyecto,p.nombre_proyecto,p.cliente,p.responsable_skilled,p.estado,p.fecha_asignacion,p.fecha_entrega,
      coalesce(nullif(p.presupuesto_materiales,0),nullif(case when p.tipo_control='presupuesto' then p.presupuesto_planeado else 0 end,0),mp.material_planeado,0),
      coalesce(mr.material_real,0),
      coalesce(nullif(p.presupuesto_sueldos,0),py.nomina_planeada,0),coalesce(py.nomina_real,0),
      coalesce(nullif(p.presupuesto_materiales,0),nullif(case when p.tipo_control='presupuesto' then p.presupuesto_planeado else 0 end,0),mp.material_planeado,0)+coalesce(nullif(p.presupuesto_sueldos,0),py.nomina_planeada,0),
      coalesce(mr.material_real,0)+coalesce(py.nomina_real,0),
      (coalesce(mr.material_real,0)+coalesce(py.nomina_real,0))-(coalesce(nullif(p.presupuesto_materiales,0),nullif(case when p.tipo_control='presupuesto' then p.presupuesto_planeado else 0 end,0),mp.material_planeado,0)+coalesce(nullif(p.presupuesto_sueldos,0),py.nomina_planeada,0))
    from public.proyectos p left join material_plan mp on mp.proyecto_numero=p.numero_proyecto left join material_real mr on mr.proyecto_numero=p.numero_proyecto left join payroll py on py.proyecto_numero=p.numero_proyecto
    order by p.fecha_entrega nulls last,p.numero_proyecto;
end;
$$;
revoke all on function public.crm_resumen_ejecutivo_proyectos() from public,anon;
grant execute on function public.crm_resumen_ejecutivo_proyectos() to authenticated;

create or replace function public.crm_detalle_ejecutivo_proyecto(p_proyecto text)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare v_summary record; v_materiales jsonb; v_personal jsonb;
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','gerente_general','subgerente','sky_demo')) then
        raise exception using errcode='42501',message='Este detalle está disponible solo para Dirección.';
    end if;
    select * into v_summary from public.crm_resumen_ejecutivo_proyectos() s where s.proyecto=p_proyecto;
    if not found then raise exception 'No se encontró el proyecto %.',p_proyecto; end if;

    with plan_lines as (
        select pm.material_codigo codigo,coalesce(m.descripcion,pm.material_codigo) descripcion,coalesce(pm.cantidad_planeada,0)::numeric cantidad_planeada,
               coalesce(nullif(pm.precio_unitario,0),m.precio,0)::numeric precio from public.proyecto_materiales pm left join public.materiales m on m.codigo=pm.material_codigo where pm.proyecto_numero=p_proyecto
        union all
        select pn.codigo_manual,coalesce(nullif(pn.descripcion,''),pn.codigo_manual),coalesce(pn.cantidad_planeada,0)::numeric,coalesce(pn.precio_unitario,0)::numeric from public.proyecto_materiales_no_listados pn where pn.proyecto_numero=p_proyecto
    ), moves as (
        select coalesce(nullif(mv.material_codigo,''),nullif(mv.codigo_manual,'')) codigo,
               sum(case when lower(coalesce(mv.tipo,''))='entrada' then coalesce(mv.cantidad,0) else 0 end)::numeric entrada,
               sum(case when lower(coalesce(mv.tipo,''))='salida' then coalesce(mv.cantidad,0) when lower(coalesce(mv.tipo,''))='reingreso' then -coalesce(mv.cantidad,0) when lower(coalesce(mv.tipo,''))='ajuste' and lower(coalesce(mv.ajuste_accion,''))='disminuir' then coalesce(mv.cantidad,0) else 0 end)::numeric entregado,
               max(coalesce(nullif(mv.precio_unitario,0),m.precio,0))::numeric precio
        from public.movimientos mv left join public.materiales m on m.codigo=mv.material_codigo where mv.proyecto=p_proyecto
        group by coalesce(nullif(mv.material_codigo,''),nullif(mv.codigo_manual,''))
    ), combined as (
        select coalesce(pl.codigo,mv.codigo) codigo,coalesce(pl.descripcion,coalesce(mat.descripcion,mv.codigo)) descripcion,coalesce(pl.cantidad_planeada,0) cantidad_planeada,
               greatest(coalesce(mv.entrada,0),greatest(coalesce(mv.entregado,0),0)) cantidad_real,
               coalesce(pl.precio,mv.precio,0) precio_plan,coalesce(mv.precio,pl.precio,0) precio_real
        from plan_lines pl full join moves mv on lower(mv.codigo)=lower(pl.codigo) left join public.materiales mat on mat.codigo=mv.codigo
    )
    select coalesce(jsonb_agg(jsonb_build_object('codigo',codigo,'descripcion',descripcion,'cantidad_planeada',cantidad_planeada,'cantidad_real',cantidad_real,'costo_planeado',cantidad_planeada*precio_plan,'costo_real',cantidad_real*precio_real,'diferencia',(cantidad_real*precio_real)-(cantidad_planeada*precio_plan)) order by codigo),'[]'::jsonb) into v_materiales from combined;

    select coalesce(jsonb_agg(jsonb_build_object(
        'numero_empleado',rp.numero_empleado,'nombre',btrim(rp.nombre||' '||rp.apellidos),'puesto',rp.puesto,'rol_proyecto',a.rol_proyecto,'fecha_inicio',a.fecha_inicio,
        'fecha_fin',coalesce(a.fecha_fin,p.fecha_entrega),'porcentaje_dedicacion',coalesce(a.porcentaje_dedicacion,100),
        'costo_planeado',(case when rp.esquema_pago='hora' then coalesce(rp.tarifa_pago,0)*greatest(coalesce(rp.horas_jornada_diaria,8)-coalesce(rp.horas_comida_diaria,1),0) else coalesce(nullif(rp.salario_semanal_calculado,0),rp.tarifa_pago,rp.salario,0)/greatest(coalesce(rp.dias_laborales_semana,6),1) end)*greatest(0,(coalesce(a.fecha_fin,p.fecha_entrega,current_date)-a.fecha_inicio+1))*greatest(coalesce(rp.dias_laborales_semana,6),1)/7.0*coalesce(a.porcentaje_dedicacion,100)/100.0,
        'costo_real',(case when rp.esquema_pago='hora' then coalesce(rp.tarifa_pago,0)*greatest(coalesce(rp.horas_jornada_diaria,8)-coalesce(rp.horas_comida_diaria,1),0) else coalesce(nullif(rp.salario_semanal_calculado,0),rp.tarifa_pago,rp.salario,0)/greatest(coalesce(rp.dias_laborales_semana,6),1) end)*greatest(0,(least(current_date,coalesce(a.fecha_fin,p.fecha_entrega,current_date))-a.fecha_inicio+1))*greatest(coalesce(rp.dias_laborales_semana,6),1)/7.0*coalesce(a.porcentaje_dedicacion,100)/100.0
    ) order by rp.apellidos,rp.nombre),'[]'::jsonb) into v_personal
    from public.rh_proyecto_asignaciones a join public.rh_personal rp on rp.id=a.personal_id join public.proyectos p on p.numero_proyecto=a.proyecto_numero
    where a.proyecto_numero=p_proyecto and a.estado<>'cancelado';

    return jsonb_build_object('proyecto',v_summary.proyecto,'nombre',v_summary.nombre,'cliente',v_summary.cliente,'responsable',v_summary.responsable,'estado',v_summary.estado,
      'material_planeado',v_summary.material_planeado,'material_real',v_summary.material_real,'nomina_planeada',v_summary.nomina_planeada,'nomina_real',v_summary.nomina_real,
      'total_planeado',v_summary.total_planeado,'total_real',v_summary.total_real,'desviacion_total',v_summary.desviacion_total,'materiales',v_materiales,'personal',v_personal);
end;
$$;
revoke all on function public.crm_detalle_ejecutivo_proyecto(text) from public,anon;
grant execute on function public.crm_detalle_ejecutivo_proyecto(text) to authenticated;

create or replace function public.crm_sky_direccion_activos_oficina()
returns jsonb
language plpgsql
stable
security definer
set search_path=public,auth
as $$
declare v_activos jsonb;v_asignaciones jsonb;
begin
    if not exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','gerente_general','subgerente','sky_demo')) then raise exception using errcode='42501',message='Esta consulta de Sky está disponible solo para Dirección.';end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'codigo',x.codigo,'nombre',x.nombre,'categoria',x.categoria,'marca',x.marca,'modelo',x.modelo,'numeroSerie',x.numero_serie,'unidad',x.unidad,'cantidadTotal',x.cantidad_total,'asignado',x.asignado,'noDisponible',x.no_disponible,'disponible',greatest(x.cantidad_total-x.no_disponible,0),'ubicacion',x.ubicacion,'estado',x.estado) order by x.nombre),'[]'::jsonb) into v_activos from (select a.*,coalesce(sum(r.cantidad) filter(where r.estado='asignado'),0) asignado,coalesce(sum(r.cantidad) filter(where r.estado in ('asignado','danado','perdido')),0) no_disponible from public.rh_activos_oficina a left join public.rh_activos_asignaciones r on r.activo_id=a.id group by a.id)x;
    select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'activoId',a.id,'activoCodigo',a.codigo,'activoNombre',a.nombre,'categoria',a.categoria,'marca',a.marca,'modelo',a.modelo,'numeroSerie',a.numero_serie,'unidad',a.unidad,'personalId',p.id,'personalNumero',p.numero_empleado,'personalNombre',btrim(coalesce(p.nombre,'')||' '||coalesce(p.apellidos,'')),'puesto',p.puesto,'departamento',p.departamento,'cantidad',r.cantidad,'fechaAsignacion',r.fecha_asignacion,'fechaDevolucion',r.fecha_devolucion,'estado',r.estado,'condicionEntrega',r.condicion_entrega,'condicionDevolucion',r.condicion_devolucion,'responsableEntrega',r.responsable_entrega,'responsableRecepcion',r.responsable_recepcion) order by r.fecha_asignacion desc,r.id desc),'[]'::jsonb) into v_asignaciones from public.rh_activos_asignaciones r join public.rh_activos_oficina a on a.id=r.activo_id join public.rh_personal p on p.id=r.personal_id;
    return jsonb_build_object('activos',v_activos,'asignaciones',v_asignaciones);
end;
$$;
revoke all on function public.crm_sky_direccion_activos_oficina() from public,anon;
grant execute on function public.crm_sky_direccion_activos_oficina() to authenticated;

